/** Site themes: a subtle wallpaper behind the whole page (themes.css, generated by scripts/biomes.py) and a touch of
 *  colour on the result boxes. Picked in the header; remembered per viewer in this browser (localStorage). */
export const THEMES = [
  { id: "forest", name: "Forest" }, { id: "city", name: "City" }, { id: "desert", name: "Desert" },
  { id: "savanna", name: "Savanna" }, { id: "volcano", name: "Volcano" }, { id: "snow", name: "Snow" },
  { id: "cave", name: "Cave" }, { id: "seafloor", name: "Seafloor" }, { id: "sky", name: "Sky" },
  { id: "plain", name: "Plain" },
] as const;
export type ThemeId = (typeof THEMES)[number]["id"];
export const DEFAULT_THEME: ThemeId = "forest";

export function loadTheme(): ThemeId {
  try {
    const t = localStorage.getItem("theme");
    if (THEMES.some((x) => x.id === t)) return t as ThemeId;
  } catch { /* storage blocked: use the default */ }
  return DEFAULT_THEME;
}
export function applyTheme(t: ThemeId) {
  document.documentElement.dataset.theme = t;
  try { localStorage.setItem("theme", t); } catch { /* not saved, still applied */ }
}
